SELECT DISTINCT EAI_SYSTEM_ID,  SERVICE_NAME,  SERVICE_LINK_NAME,  (    SELECT QUEUE_DESCRIPTION    FROM TB_S60_QNAM010    WHERE SERVICE_LINK_NAME = LOCAL_QUEUE_NAME ) DESCRIPTION,  BL_STATUS,  TO_CHAR(LAST_UPDATE_TIMESTAMP, 'YYYY/MM/DD HH24:MI:SS') LAST_UPDATE_TIMESTAMP,  STATUS_SEQ_ID,  DESCRIPTION,  TO_CHAR(DATA_ACCRUAL_TIME, 'YYYY/MM/DD HH24:MI:SS') DATA_ACCRUAL_TIMEFROM (    SELECT IFMG.INTERFACE_SECTION,      SMLS.EAI_SYSTEM_ID,      SMLS.SERVICE_NAME,      SMLS.SERVICE_LINK_NAME,      SMLS.BL_STATUS,      SMLS.LAST_UPDATE_TIMESTAMP,      SMLS.STATUS_SEQ_ID,      SMLS.DESCRIPTION,	  SMLS.DATA_ACCRUAL_TIME    FROM TB_S60_STAT020 SMLS,      TB_S60_IFMG020 IFMG    WHERE SMLS.EAI_SYSTEM_ID = IFMG.SEND_EAI_SYSTEM_ID      AND SMLS.SERVICE_NAME = IFMG.SEND_APP_NAME      AND SMLS.SERVICE_LINK_NAME = IFMG.SEND_LINK_NAME    UNION ALL    SELECT IFMG.INTERFACE_SECTION,      SMLS.EAI_SYSTEM_ID,      SMLS.SERVICE_NAME,      SMLS.SERVICE_LINK_NAME,      SMLS.BL_STATUS,      SMLS.LAST_UPDATE_TIMESTAMP,      SMLS.STATUS_SEQ_ID,      SMLS.DESCRIPTION,      SMLS.DATA_ACCRUAL_TIME    FROM TB_S60_STAT020 SMLS,      TB_S60_IFMG020 IFMG    WHERE SMLS.EAI_SYSTEM_ID = IFMG.RECV_EAI_SYSTEM_ID      AND SMLS.SERVICE_NAME = IFMG.RECV_APP_NAME      AND SMLS.SERVICE_LINK_NAME = IFMG.RECV_LINK_NAME )WHERE INTERFACE_SECTION LIKE CONCAT(? , '%')  AND EAI_SYSTEM_ID LIKE CONCAT(? , '%')  AND SERVICE_NAME LIKE CONCAT(? , '%')  AND SERVICE_LINK_NAME LIKE CONCAT(? , '%')  AND LAST_UPDATE_TIMESTAMP IS NOT NULL   ORDER BY BL_STATUS, SERVICE_NAME, LAST_UPDATE_TIMESTAMP